{
    "title": "Complete English Course",
    "description": "Structured course from A0 to C1 for Spanish-speaking learners",
    "levels": [
        {
            "levelName": "A0",
            "lessons": [
                {
                    "title": "Introduction to English",
                    "description": "Basic greetings, alphabet, and numbers",
                    "level": "A0",
                    "order": 1,
                    "practiceExercises": [
                        "exercise1.pdf",
                        "exercise2.pdf"
                    ],
                    "resources": [
                        "video1.mp4",
                        "slides1.pdf"
                    ]
                },
                {
                    "title": "Simple Sentences",
                    "description": "Forming basic sentences",
                    "level": "A0",
