                        "exercise3.pdf"
                    ],
                    "resources": [
                        "video2.mp4"
                    ]
                }
            ]
        },
        {
            "levelName": "A1",
            "lessons": [
                {
                    "title": "Past Simple",
                    "description": "Learn how to form and use past simple tense",
                    "level": "A1",
                    "order": 1,
                    "practiceExercises": [
                        "exercise1.pdf"
                    ],
                    "resources": [
                        "video1.mp4"
                    ]
                },
                {
                    "title": "Future Tense",
                    "description": "Introduction to simple future tense",
                    "level": "A1",
                    "order": 2,
                    "practiceExercises": [
                        "exercise2.pdf"
                    ],
                    "resources": [
                        "video2.mp4"
                    ]
                }
            ]
        },
        {
            "levelName": "A2",
            "lessons": [
                {
                    "title": "Present Perfect",
                    "description": "Using present perfect in conversation",
                    "level": "A2",
                    "order": 1,
                    "practiceExercises": [
                        "exercise1.pdf"
                    ],
